// Animated method figures: replaces <figure data-flow-figure="name"> with an inline SVG that plays
// the data flow step by step, with a Training/Inference toggle. If the SVG cannot be fetched, the
// static <img> stays in place. SVGs are generated by tools/flow-figures/build.js.
//
// Every frame is a pure function of time t (see Figure.render), so Replay and the toggle just reset
// t, reduced motion jumps to the end, and the video export can seek frame by frame.
(() => {
  'use strict';

  const SVG_NS = 'http://www.w3.org/2000/svg';
  const PENDING_OPACITY = 0.35; // in this mode, but the flow has not reached it yet
  const GHOST_OPACITY = 0.25; // an arrow before it is drawn
  const FADE = 0.25; // seconds for a block to light up
  const HOLD = 0.35; // seconds an arrival stays highlighted
  const GAP = 0.18; // seconds between steps
  const TOKEN_COLOR = '#e8590c';
  const NEGATIVE = '#990000';

  // Both frame blocks supply negatives only (Eq. 11 of the paper), so their tokens end at the H^i dot.
  // The positive y+ comes from the demonstrated future frame (Eq. 10), which this figure does not draw.
  const NEGATIVE_TOKEN = [{ color: NEGATIVE, then: 'L 287.5 58.7' }];

  // A step can list: edges to draw; `appear`, edges that show without any data moving along them;
  // `light` or `from` blocks, highlighted while the step runs; `to` blocks, highlighted on arrival;
  // and `pulse` cells. Blocks and edges a mode never mentions are dimmed, and `hidden` ones are
  // removed. Steps play one after another, in the order listed.
  const FIGURES = {
    implicit: {
      src: './static/images/flow/implicit.svg',
      prefix: 'impl',
      modes: {
        training: {
          hidden: ['policy', 'tok-policy'],
          steps: [
            { light: ['eq-u'], dur: 0.9 },
            { light: ['eq-e'], dur: 0.9 },
            { edges: ['eq-tok'], from: ['eq-e', 'vlm'], to: ['tokens'], dur: 1.0 },
            { edges: ['tok-proj-a', 'tok-proj-b'], from: ['tokens'], to: ['proj', 'eq-z'], dur: 0.6 },
            { edges: ['proj-z'], from: ['proj'], to: ['circle', 'z'], dur: 0.6 },
            { light: ['eq-y', 'ypos'], dur: 0.9 },
            { edges: ['vwm-nr'], from: ['vwm', 'synthetic'], to: ['nr'], dur: 1.2 },
            { edges: ['nr-circle'], tokens: NEGATIVE_TOKEN, from: ['nr', 'fenc'], to: ['yneg'], dur: 1.3 },
            // World-model rollouts start from the current observation, not from this block (Sec. III-C),
            // so no data moves along the Cross-Episode -> Video World Model arrow.
            { appear: ['ce-vwm'], edges: ['ce-circle'], tokens: NEGATIVE_TOKEN, from: ['ce', 'fenc'], to: ['yneg'], dur: 1.5 },
            { edges: ['z-ypos', 'z-yneg'], from: ['z', 'circle'], pulse: ['y-pos', 'y-neg'], dur: 1.6 },
          ],
        },
        inference: {
          steps: [
            { light: ['eq-u'], dur: 0.9 },
            { light: ['eq-e'], dur: 0.9 },
            { edges: ['eq-tok'], from: ['eq-e', 'vlm'], to: ['tokens'], dur: 1.0 },
            { edges: ['tok-policy'], from: ['tokens'], to: ['policy'], dur: 1.0 },
          ],
        },
      },
      // Phones: stack the equations under the diagram so the labels stay readable.
      narrow: {
        query: '(max-width: 600px)',
        viewBox: '8 8 312 304',
        move: { equations: 'translate(-294 160)', policy: 'translate(-101 27)', vlm: 'translate(-49 96)' },
        edges: {
          'eq-tok': 'M 187.6 238 L 300 238 Q 306 238 306 232 L 306 152.4 Q 306 146.4 300 146.4 L 292.9 146.4',
          'tok-policy': 'M 284.2 151.5 L 284.2 177',
        },
      },
    },
    explicit: {
      src: './static/images/flow/explicit.svg',
      prefix: 'expl',
      modes: {
        training: {
          hidden: ['policy', 'tok-policy'],
          steps: [
            { light: ['eq-q'], dur: 0.9 },
            { light: ['eq-e'], dur: 0.9 },
            { edges: ['eq-tok'], from: ['eq-e', 'vlm'], to: ['tokens'], dur: 1.4 },
            { edges: ['tok-sgad-a', 'tok-sgad-b'], from: ['tokens'], to: ['sgad', 'eq-sgad'], dur: 0.5 },
            { edges: ['sgad-ghat', 'sgad-shat'], from: ['sgad', 'eq-sgad'], to: ['fs', 'ghat', 'shat'], dur: 1.1 },
            { edges: ['rgb-geo', 'rgb-pe'], from: ['rgb'], to: ['geo', 'pe', 'eq-t'], dur: 1.2 },
            { edges: ['geo-g', 'pe-s'], from: ['geo', 'pe', 'eq-t'], to: ['g', 's'], dur: 0.7 },
            { edges: ['cmp-g', 'cmp-s'], tokens: [], from: ['ghat', 'g', 'shat', 's'], dur: 0.9 },
            { light: ['eq-l', 'fs'], dur: 1.4 },
          ],
        },
        inference: {
          steps: [
            { light: ['eq-q'], dur: 0.9 },
            { light: ['eq-e'], dur: 0.9 },
            { edges: ['eq-tok'], from: ['eq-e', 'vlm'], to: ['tokens'], dur: 1.4 },
            { edges: ['tok-policy'], from: ['tokens'], to: ['policy'], dur: 0.8 },
          ],
        },
      },
      narrow: {
        query: '(max-width: 600px)',
        viewBox: '8 8 280 332',
        move: { equations: 'translate(-251.1 190.3) scale(0.87)', vlm: 'translate(-97 7)' },
        edges: { 'eq-tok': 'M 14 250.4 L 14 170 Q 14 164.5 20 164.5 L 38 164.5' },
      },
    },
  };

  const clamp01 = (x) => Math.min(1, Math.max(0, x));
  const smooth = (u) => u * u * (3 - 2 * u);
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');

  /* Turns a mode's steps into absolute times. */
  function compile(mode) {
    const plan = { blocks: {}, edges: {}, pulses: [], hidden: new Set(mode.hidden), duration: 0 };
    const mark = (name, start, end) => {
      const block = plan.blocks[name] || (plan.blocks[name] = { lit: start, active: [] });
      block.lit = Math.min(block.lit, start);
      block.active.push([start, end]);
      plan.duration = Math.max(plan.duration, end);
    };
    let t = 0;
    for (const step of mode.steps) {
      const end = t + step.dur;
      [...(step.light || []), ...(step.from || [])].forEach((b) => mark(b, t, end));
      (step.to || []).forEach((b) => mark(b, end, end + HOLD));
      (step.edges || []).forEach((e) => { plan.edges[e] = { start: t, end, tokens: step.tokens }; });
      (step.appear || []).forEach((e) => { plan.edges[e] = { start: t, end: t, tokens: [] }; });
      (step.pulse || []).forEach((id) => plan.pulses.push({ id, start: t, end }));
      plan.duration = Math.max(plan.duration, end);
      t = end + GAP;
    }
    return plan;
  }

  /* Dash pattern showing the first fraction p of a line, keeping the line's own dashes if it has any. */
  function revealDash(pattern, length, p) {
    const out = [];
    let used = 0;
    for (let i = 0; used < length * p; i += 1) {
      const dash = Math.min(pattern ? pattern[i % pattern.length] : length, length * p - used);
      out.push(dash);
      used += dash;
    }
    if (out.length % 2) out.push(length);
    else out[out.length - 1] += length;
    return out.join(' ');
  }

  /* An arrow: a faint ghost of the full line, a drawn copy revealed over it, a head, and its tokens. */
  class Edge {
    constructor(group) {
      this.group = group;
      this.line = group.querySelector('.flow-line');
      this.heads = [...group.querySelectorAll('.flow-head')];
      this.drawn = this.line.cloneNode();
      this.drawn.setAttribute('class', 'flow-drawn');
      this.line.after(this.drawn);
      const dashes = this.line.getAttribute('stroke-dasharray');
      this.pattern = dashes ? dashes.trim().split(/[\s,]+/).map(Number) : null;
      this.autoHead = !this.heads[0].hasAttribute('d');
      this.wideD = this.line.getAttribute('d');
      this.tokens = [];
      this.setPath(this.wideD);
    }

    setPath(d) {
      this.line.setAttribute('d', d);
      this.drawn.setAttribute('d', d);
      this.length = this.line.getTotalLength();
      if (this.autoHead) this.drawHead();
      this.tokens.forEach((token) => this.measureToken(token));
      this.lastP = null;
    }

    /* Same proportions as draw.io's own arrowheads, smaller on very short arrows. */
    drawHead() {
      const tip = this.line.getPointAtLength(this.length);
      const prev = this.line.getPointAtLength(this.length - 0.5);
      const size = this.length < 20 ? 0.7 : 1;
      const ux = (tip.x - prev.x) / 0.5;
      const uy = (tip.y - prev.y) / 0.5;
      const at = (back, side) => `${tip.x - ux * back * size - uy * side * size} ${tip.y - uy * back * size + ux * side * size}`;
      this.heads[0].setAttribute('d', `M ${tip.x} ${tip.y} L ${at(7, 3.5)} L ${at(5.25, 0)} L ${at(7, -3.5)} Z`);
    }

    measureToken(token) {
      token.routeLength = token.route.getTotalLength();
    }

    setTokens(defs) {
      this.tokens.forEach((token) => { token.el.remove(); if (token.route !== this.line) token.route.remove(); });
      const stroke = this.line.getAttribute('stroke');
      const fallback = stroke === '#000' || stroke === '#000000' ? TOKEN_COLOR : stroke;
      this.tokens = (defs || [{}]).map((def) => {
        const el = document.createElementNS(SVG_NS, 'circle');
        el.setAttribute('class', 'flow-token');
        el.setAttribute('r', '2.6');
        el.setAttribute('fill', def.color || fallback);
        let route = this.line;
        if (def.then) {
          route = document.createElementNS(SVG_NS, 'path');
          route.setAttribute('d', `${this.line.getAttribute('d')} ${def.then}`);
          route.setAttribute('fill', 'none');
          this.group.appendChild(route);
        }
        // Inserted beside the line, so a token passes behind labels that sit above its arrow.
        this.line.parentNode.appendChild(el);
        const token = { el, route, delay: def.delay || 0 };
        this.measureToken(token);
        return token;
      });
    }

    clearTokens() {
      this.setTokens([]);
    }

    show(state, timing, t) {
      this.group.classList.toggle('is-hidden', state === 'hidden');
      this.group.classList.toggle('is-off', state === 'off');
      if (state !== 'on') {
        this.line.style.opacity = '';
        this.heads.forEach((head) => { head.style.opacity = ''; });
        this.drawn.style.display = 'none';
        this.lastP = null;
        return;
      }
      const span = timing.end - timing.start;
      // Without a token, the line just draws itself over the step.
      let p = span > 0 ? smooth(clamp01((t - timing.start) / span)) : 0;
      this.tokens.forEach((token, i) => {
        const u = smooth(clamp01((t - timing.start - token.delay * span) / (span * (1 - token.delay))));
        const inFlight = u > 0 && u < 1;
        token.el.style.display = inFlight ? '' : 'none';
        if (inFlight) {
          const at = token.route.getPointAtLength(token.routeLength * u);
          token.el.setAttribute('cx', at.x);
          token.el.setAttribute('cy', at.y);
        }
        if (i === 0) p = clamp01((token.routeLength * u) / this.length);
      });
      if (t >= timing.end) p = 1;
      if (p !== this.lastP) {
        this.lastP = p;
        this.drawn.style.display = p > 0 ? '' : 'none';
        if (p > 0) this.drawn.style.strokeDasharray = p >= 1 ? (this.pattern ? this.pattern.join(' ') : 'none') : revealDash(this.pattern, this.length, p);
        this.line.style.opacity = GHOST_OPACITY;
        this.heads.forEach((head) => { head.style.opacity = p >= 1 ? 1 : GHOST_OPACITY; });
      }
    }
  }

  class Figure {
    constructor(cfg, svg, host) {
      this.cfg = cfg;
      this.svg = svg;
      this.t = 0;
      this.visible = false;
      this.started = false;
      this.frozen = false;
      this.raf = null;
      this.tick = this.tick.bind(this);

      this.blocks = new Map();
      svg.querySelectorAll('[data-block]').forEach((el) => {
        if (!this.blocks.has(el.dataset.block)) this.blocks.set(el.dataset.block, { els: [], key: '' });
        this.blocks.get(el.dataset.block).els.push(el);
      });
      this.edges = new Map();
      svg.querySelectorAll('[data-edge]').forEach((g) => this.edges.set(g.dataset.edge, new Edge(g)));
      this.pulses = new Map();

      this.wideViewBox = svg.getAttribute('viewBox');
      if (cfg.narrow) {
        this.narrow = matchMedia(cfg.narrow.query);
        this.narrow.addEventListener('change', () => { this.applyLayout(); this.render(this.t); });
        this.applyLayout();
      }

      this.buildControls(host);
      this.setMode('training', { play: false });
      this.observe(host);
    }

    applyLayout() {
      const { viewBox, move, edges } = this.cfg.narrow;
      const on = this.narrow.matches;
      this.svg.setAttribute('viewBox', on ? viewBox : this.wideViewBox);
      for (const id of Object.keys(move)) {
        const el = this.svg.getElementById(`${this.cfg.prefix}-${id}`);
        if (on) el.setAttribute('transform', move[id]);
        else el.removeAttribute('transform');
      }
      for (const name of Object.keys(edges)) {
        const edge = this.edges.get(name);
        edge.setPath(on ? edges[name] : edge.wideD);
      }
    }

    buildControls(host) {
      const bar = document.createElement('div');
      bar.className = 'flow-controls';
      const group = document.createElement('div');
      group.className = 'flow-toggle';
      group.setAttribute('role', 'group');
      group.setAttribute('aria-label', 'Show the data flow during');
      this.modeButtons = Object.keys(this.cfg.modes).map((mode) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = mode[0].toUpperCase() + mode.slice(1);
        b.dataset.mode = mode;
        b.addEventListener('click', () => this.setMode(mode));
        group.appendChild(b);
        return b;
      });
      this.replay = document.createElement('button');
      this.replay.type = 'button';
      this.replay.className = 'flow-replay';
      this.replay.innerHTML = '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M8 3a5 5 0 1 1-4.6 3" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><path d="M8 .6v4.8L4.8 3z" fill="currentColor"/></svg>Replay';
      this.replay.addEventListener('click', () => this.restart());
      bar.append(group, this.replay);
      host.prepend(bar);
    }

    setMode(mode, { play = true } = {}) {
      this.mode = mode;
      this.plan = compile(this.cfg.modes[mode]);
      this.svg.dataset.mode = mode;
      this.modeButtons.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.mode === mode)));
      this.edges.forEach((edge, name) => {
        const timing = this.plan.edges[name];
        if (timing) edge.setTokens(timing.tokens);
        else edge.clearTokens();
      });
      this.blocks.forEach((block) => { block.key = ''; });
      if (play) this.restart();
      else this.render(0);
    }

    restart() {
      this.started = true;
      this.stop();
      if (reducedMotion.matches) {
        this.replay.hidden = true;
        this.render(this.plan.duration);
        return;
      }
      this.replay.hidden = false;
      this.render(0);
      this.run();
    }

    run() {
      if (this.frozen || !this.visible || this.t >= this.plan.duration || reducedMotion.matches) return;
      this.last = null;
      this.raf = requestAnimationFrame(this.tick);
    }

    stop() {
      if (this.raf !== null) cancelAnimationFrame(this.raf);
      this.raf = null;
    }

    /* Hands control of time to the caller, who then steps through frames with render(t). */
    freeze() {
      this.frozen = true;
      this.stop();
    }

    tick(now) {
      // Capped so that returning from a background tab resumes rather than jumps.
      const dt = this.last === null ? 0 : Math.min(0.1, (now - this.last) / 1000);
      this.last = now;
      this.render(Math.min(this.plan.duration, this.t + dt));
      this.raf = this.t < this.plan.duration ? requestAnimationFrame(this.tick) : null;
    }

    /* Autoplays on first sight, and pauses while scrolled out of view. */
    observe(host) {
      new IntersectionObserver((entries) => {
        this.visible = entries[entries.length - 1].isIntersecting;
        if (this.frozen) return;
        if (!this.visible) this.stop();
        else if (!this.started) this.restart();
        else if (this.raf === null) this.run();
      }, { threshold: 0.3 }).observe(host);
    }

    render(t) {
      this.t = t;
      const { plan } = this;
      this.blocks.forEach((block, name) => this.renderBlock(block, name, t));
      this.edges.forEach((edge, name) => {
        const timing = plan.edges[name];
        if (plan.hidden.has(name)) edge.show('hidden');
        else if (timing) edge.show('on', timing, t);
        else edge.show('off');
      });
      this.pulses.forEach((ring) => { ring.style.display = 'none'; });
      for (const { id, start, end } of plan.pulses) {
        const u = (t - start) / (end - start);
        if (u > 0 && u < 1) this.renderPulse(id, (u * 2) % 1);
      }
    }

    renderBlock(block, name, t) {
      const { plan } = this;
      const info = plan.blocks[name];
      const hidden = plan.hidden.has(name);
      const off = !hidden && !info;
      let opacity = '';
      let active = false;
      if (info && !hidden) {
        const lit = clamp01((t - info.lit) / FADE);
        opacity = t < info.lit ? PENDING_OPACITY : (PENDING_OPACITY + (1 - PENDING_OPACITY) * lit).toFixed(3);
        active = info.active.some(([start, end]) => t >= start && t < end);
      }
      const key = `${hidden}|${off}|${opacity}|${active}`;
      if (key === block.key) return;
      block.key = key;
      for (const el of block.els) {
        el.classList.toggle('is-hidden', hidden);
        el.classList.toggle('is-off', off);
        el.classList.toggle('is-active', active);
        el.style.opacity = opacity;
      }
    }

    renderPulse(id, f) {
      let ring = this.pulses.get(id);
      if (!ring) {
        const dot = this.svg.getElementById(`${this.cfg.prefix}-${id}`);
        const box = dot.getBBox();
        ring = document.createElementNS(SVG_NS, 'circle');
        ring.setAttribute('class', 'flow-pulse');
        ring.setAttribute('cx', box.x + box.width / 2);
        ring.setAttribute('cy', box.y + box.height / 2);
        ring.setAttribute('stroke', dot.querySelector('ellipse').getAttribute('fill'));
        ring.dataset.r = box.width / 2;
        dot.parentNode.appendChild(ring);
        this.pulses.set(id, ring);
      }
      ring.style.display = '';
      ring.setAttribute('r', Number(ring.dataset.r) + 8 * f);
      ring.style.opacity = 0.85 * (1 - f);
    }
  }

  const instances = {};

  const mountAll = [...document.querySelectorAll('[data-flow-figure]')].map(async (host) => {
    const name = host.dataset.flowFigure;
    const cfg = FIGURES[name];
    const img = host.querySelector('img');
    try {
      const response = await fetch(cfg.src);
      if (!response.ok) throw new Error(`${cfg.src}: ${response.status}`);
      const holder = document.createElement('div');
      holder.innerHTML = await response.text();
      const svg = holder.querySelector('svg');
      svg.setAttribute('role', 'img');
      svg.setAttribute('aria-label', img.alt);
      img.replaceWith(svg);
      host.classList.add('flow-figure');
      instances[name] = new Figure(cfg, svg, host);
    } catch (err) {
      console.warn('Flow figure unavailable, keeping the static image.', err);
    }
  });

  // Used by tools/flow-figures/export.js to step through frames.
  window.FlowFigures = {
    ready: Promise.all(mountAll),
    get: (name) => instances[name],
  };
})();
